// Service layer — generated by line-matcher. Do not add logic that belongs to another layer.
// External I/O only: one function per API endpoint.

async function request(method, url, body) {
  const res = await fetch(url, {
    method,
    headers: body ? { "Content-Type": "application/json" } : undefined,
    body: body ? JSON.stringify(body) : undefined,
  });
  if (!res.ok) throw new Error(`${method} ${url} failed with ${res.status}`);
  return res.status === 204 ? null : res.json();
}

export const listOrgsItems = () => request("GET", `/api/items`);
export const createOrgsItem = (data) => request("POST", `/api/items`, data);
export const updateOrgsItem = (id, data) =>
  request("PUT", `/api/items/${encodeURIComponent(id)}`, data);
export const deleteOrgsItem = (id) => request("DELETE", `/api/items/${encodeURIComponent(id)}`);
export const getApiOrgsItems = (orgId, id) =>
  request("GET", `/api/orgs/${encodeURIComponent(orgId)}/items/${encodeURIComponent(id)}`);
